action.code:
if (n <= 0 || bits_per_key < 0) {
    dst->clear();
    return;
}

const size_t bits = static_cast<size_t>(n * bits_per_key);
const size_t bytes = (bits + 7) / 8;
const size_t k = static_cast<size_t>(bits_per_key * 0.69);  // 0.69 ≈ ln(2)
const size_t k_probes = k < 1 ? 1 : k > 30 ? 30 : k;

dst->resize(bytes + 1, 0);
char* array = &(*dst)[0];

for (int i = 0; i < n; ++i) {
    const uint32_t h = std::hash<std::string_view>()(std::string_view(keys[i].data(), keys[i].size()));
    const uint32_t delta = (h >> 17) | (h << 15);
    for (size_t j = 0; j < k_probes; ++j) {
        const uint32_t bitpos = h + j * delta;
        array[bitpos / 8] |= (1 << (bitpos % 8));
    }
}

(*dst)[bytes] = static_cast<char>(k_probes);
// END_CODE

